const EMBEDDING_MODEL = 'gemini-embedding-2';
const EMBEDDING_DIMENSIONS = 768;
const rawItems = $input.all();
return rawItems.map((item) => {
  const row = item.json || {};
  if (!Number.isInteger(Number(row.example_id)) || typeof row.pattern_name !== 'string' || typeof row.example_text !== 'string' || !row.example_text.trim()) {
    throw new Error('A curated embedding row is malformed.');
  }
  return {
    json: {
      example_id: Number(row.example_id),
      embedding_model: EMBEDDING_MODEL,
      embedding_dimensions: EMBEDDING_DIMENSIONS,
      embedding_url: 'https://generativelanguage.googleapis.com/v1beta/models/' + EMBEDDING_MODEL + ':embedContent',
      embedding_request: {
        model: 'models/' + EMBEDDING_MODEL,
        content: {
          parts: [{
            text: 'title: ' + row.pattern_name.trim() + ' | text: ' + row.example_text.trim()
          }]
        },
        output_dimensionality: EMBEDDING_DIMENSIONS
      }
    }
  };
});

const EMBEDDING_MODEL = 'gemini-embedding-2';
const EMBEDDING_DIMENSIONS = 768;
const responses = $input.all();
const requests = $('Build Curated Embedding Requests').all();
if (responses.length !== requests.length) throw new Error('Curated embedding response count mismatch.');
return responses.map((item, index) => {
  const response = item.json || {};
  const request = requests[index] && requests[index].json;
  const status = Number(response.statusCode ?? response.status ?? 200);
  if (response.error || !Number.isInteger(status) || status < 200 || status >= 300) {
    throw new Error('Curated embedding provider request failed.');
  }
  let body = response.body ?? response;
  if (typeof body === 'string') {
    try { body = JSON.parse(body); } catch { throw new Error('Curated embedding provider returned malformed JSON.'); }
  }
  const values = body && body.embedding && Array.isArray(body.embedding.values)
    ? body.embedding.values
    : body && Array.isArray(body.embeddings) && body.embeddings[0] && Array.isArray(body.embeddings[0].values)
      ? body.embeddings[0].values
      : null;
  if (!values || values.length !== EMBEDDING_DIMENSIONS || values.some((value) => typeof value !== 'number' || !Number.isFinite(value))) {
    throw new Error('Curated embedding provider returned an invalid vector dimension.');
  }
  return {
    json: {
      example_id: request.example_id,
      embedding_model: EMBEDDING_MODEL,
      embedding_dimensions: EMBEDDING_DIMENSIONS,
      embedding_literal: JSON.stringify(values)
    }
  };
});

const rows = $input.all().map((item) => item.json || {});
if (rows.some((row) => row.error)) throw new Error('Curated embedding database update failed.');
return [{
  json: {
    ok: true,
    embedding_model: 'gemini-embedding-2',
    embedding_dimensions: 768,
    updated_example_count: rows.length
  }
}];
